        if cls2 in lk:
            lk[cls] = lk[cls2]
            return lk[cls2]
    raise TypeError(f"No dispatch for {cls}")

def __call__(self, arg, *args, **kwargs):
    """
    Call the corresponding method based on type of argument.
    """
    meth = self.dispatch(type(arg))
    return meth(arg, *args, **kwargs)

